package com.shazwan.idash;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Phase6B: real Activity geometry, official cached prayers and original-APK baseline. */
public class CompactChecks extends Instrumentation {
 LauncherActivity a;Bundle args;int count;Map<String,?> saved;SharedPreferences prefs;StringBuilder report=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);count++;}
 View find(View root,String name){return new ControlLayoutChecks().find(root,name);}
 boolean full(View v){Rect r=new Rect();return v!=null&&v.getGlobalVisibleRect(r)&&r.width()==v.getWidth()&&r.height()==v.getHeight();}
 void textFits(View root){if(root.getVisibility()!=View.VISIBLE)return;if(root instanceof TextView){TextView t=(TextView)root;android.text.Layout l=t.getLayout();if(l!=null&&t.length()>0){check(l.getLineBottom(l.getLineCount()-1)<=t.getHeight()-t.getExtendedPaddingTop()-t.getExtendedPaddingBottom()+1,"text height: "+t.getText());for(int n=0;n<l.getLineCount();n++){check(l.getEllipsisCount(n)==0,"text not ellipsized: "+t.getText());check(l.getLineWidth(n)<=l.getWidth()+1,"text fits width: "+t.getText());}}}if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++)textFits(g.getChildAt(i));}}
 void photo(String name)throws Exception{Thread.sleep(800);waitForIdleSync();Bitmap b=getUiAutomation().takeScreenshot();check(b!=null,"actual screenshot");try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 void ready()throws Exception{CountDownLatch latch=new CountDownLatch(1);a.worker.execute(()->a.main.post(latch::countDown));check(latch.await(45,TimeUnit.SECONDS),"worker barrier");waitForIdleSync();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(prefs.getAll());a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();
  ui(()->{new GlassAppearance(0,45,1,0,1,false,true).save(a);a.prefs.edit().putBoolean("calendar",true).putBoolean("jakim",true).putBoolean("prayer_countdown",true).putInt("dock_size",0).putBoolean("24h",true).apply();a.page="home";a.panelVisible=false;a.setJakimZone("SGR02");a.render();});ready();
  boolean after=!"before".equals(args.getString("phase","after"));String size=args.getString("screen",a.getResources().getDisplayMetrics().widthPixels+"x"+a.getResources().getDisplayMetrics().heightPixels);String tag="6b-"+(after?"after":"before")+"-"+size+args.getString("suffix","");
  ui(()->{if("true".equals(args.getString("bars"))){if("true".equals(args.getString("statusbar")))a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);a.getWindow().getDecorView().setSystemUiVisibility(0);}});Thread.sleep(700);waitForIdleSync();
  ui(()->{check(a.loadedZone.equals("SGR02"),"official zone loaded");JakimCalendar.Day day=a.jakimDays.get(JakimCalendar.key(System.currentTimeMillis()));check(day!=null,"official current day available");for(String time:day.times)check(a.jakimText.getText().toString().contains(time),"all six official times retained");
   View clock=find(a.stage,"Clock widget"),prayer=find(a.stage,"JAKIM calendar widget"),calendar=find(a.stage,"Calendar widget");report.append("dashboard clock=").append(full(clock)).append(" prayers=").append(full(prayer)).append(" calendar=").append(full(calendar)).append(" density=").append(a.getResources().getDisplayMetrics().density).append(" fontScale=").append(a.getResources().getConfiguration().fontScale).append('\n');
   if(after){for(View v:new View[]{clock,prayer,calendar}){check(full(v),"complete left card: "+v.getContentDescription());check(v.getHeight()>=a.dp(48),"left card touch target");textFits(v);}check(clock.getParent()==prayer.getParent()&&prayer.getParent()==calendar.getParent(),"original left stack retained");check(clock.getBottom()<=prayer.getTop()&&prayer.getBottom()<=calendar.getTop(),"clock-prayers-calendar order");for(View v=clock;v!=null;){check(!(v instanceof ScrollView),"left stack has no scrolling parent");android.view.ViewParent parent=v.getParent();v=parent instanceof View?(View)parent:null;}check(a.clock.getWidth()<a.stage.getWidth()/2,"clock stays on left");}
  });photo(tag+"-dashboard.png");
  ui(a::controlCenter);Thread.sleep(800);waitForIdleSync();
  ui(()->{View decor=a.quickControls.dialog.getWindow().getDecorView();if(after){for(String name:new String[]{"Connectivity card","Media card","System brightness","Media volume","Done","Panel","Wallpapers","Brightness access / Display"}){View v=find(decor,name);check(v!=null&&full(v),"retained control visible: "+name);check(v.getWidth()>=a.dp(48)&&v.getHeight()>=a.dp(48),"retained target48dp: "+name);}check(new ControlLayoutChecks().findText(decor,"Focus")==null,"Focus absent");for(String name:new String[]{"Airplane","Connections","Settings","Timer","Calculator","Camera","Flashlight"})check(new ControlLayoutChecks().findText(decor,name)==null,"removed control absent: "+name);for(View v:new View[]{(View)a.quickControls.wifi.getParent(),(View)a.quickControls.bluetooth.getParent(),a.quickControls.mediaControl.previous,a.quickControls.mediaControl.play,a.quickControls.mediaControl.next}){check(full(v),"radio/transport visible");check(v.getWidth()>=a.dp(48)&&v.getHeight()>=a.dp(48),"radio/transport touch48dp");}check(a.quickControls.volume instanceof CapsuleSlider&&a.quickControls.brightness instanceof CapsuleSlider,"capsule interfaces retained");check(!a.quickControls.utilitiesControl.active&&!a.quickControls.utilitiesControl.receiverRegistered,"removed utility UI starts no callbacks");textFits(a.quickControls.permission);}
  });photo(tag+"-control-center.png");
  if(after){ui(()->{find(a.quickControls.dialog.getWindow().getDecorView(),"Done").performClick();check(a.quickControls.dialog==null&&!a.quickControls.observing,"Done closes and releases");a.controlCenter();find(a.quickControls.dialog.getWindow().getDecorView(),"Wallpapers").performClick();check(a.wallpaperDialog!=null&&a.wallpaperDialog.isShowing(),"raised Wallpapers action works");a.wallpaperDialog.dismiss();a.controlCenter();find(a.quickControls.dialog.getWindow().getDecorView(),"Panel").performClick();check(a.panelVisible&&a.panelBox!=null,"raised Panel action works");a.panelVisible=false;a.render();a.controlCenter();find(a.quickControls.dialog.getWindow().getDecorView(),"Brightness access / Display").performClick();});long until=SystemClock.elapsedRealtime()+12000;while(a.resumed&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(!a.resumed,"raised brightness access opens Android Activity");try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -n com.shazwan.idash/.LauncherActivity");InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] bytes=new byte[1024];while(in.read(bytes)!=-1){}}until=SystemClock.elapsedRealtime()+12000;while(!a.resumed&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.resumed,"return from raised brightness access");}
  result.putString("stream","PASS: "+count+" compact dashboard/control checks\n"+report);code=Activity.RESULT_OK;
 }catch(Throwable t){try{ui(()->{View widgets=find(a.stage,"Dashboard widgets");Rect visible=new Rect();a.getWindow().getDecorView().getWindowVisibleDisplayFrame(visible);WindowInsets insets=a.stage.getRootWindowInsets();report.append("geometry stageH=").append(a.stage.getHeight()).append(" decorH=").append(a.getWindow().getDecorView().getHeight()).append(" shellH=").append(a.shell.getHeight()).append(" shellPadding=").append(a.shell.getPaddingTop()).append(",").append(a.shell.getPaddingBottom()).append(" bodyH=").append(a.body.getHeight()).append(" widgetsH=").append(widgets==null?-1:widgets.getHeight()).append(" visibleFrame=").append(visible).append(" rootInsets=").append(insets).append('\n');for(String name:new String[]{"Clock widget","JAKIM calendar widget","Calendar widget"}){View v=find(a.stage,name);Rect rect=new Rect();if(v!=null)v.getGlobalVisibleRect(rect);report.append(name).append(" H=").append(v==null?-1:v.getHeight()).append(" visible=").append(rect).append('\n');}});photo("compact-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL after "+count+": "+t+"\n"+report);}finally{if(prefs!=null&&saved!=null)AppearanceChecks.restore(prefs,saved);if(a!=null)ui(()->{if(a.quickControls!=null)a.quickControls.close();if(a.wallpaperDialog!=null)a.wallpaperDialog.dismiss();a.finish();});}finish(code,result);}
}
